const $=id=>document.getElementById(id),tokenKey='rebound-focus-device';let revision=0,state={terms:[],holidays:[],subjects:[],blocks:[],exams:[]};const token=()=>{let v=localStorage.getItem(tokenKey);if(!/^[a-f0-9]{64}$/.test(v||'')){v=[...crypto.getRandomValues(new Uint8Array(32))].map(n=>n.toString(16).padStart(2,'0')).join('');localStorage.setItem(tokenKey,v);}return v};const esc=x=>String(x).replace(/[<>&"]/g,'');const call=async(method,body)=>{const r=await fetch('/api/academic',{method,headers:{Authorization:`Bearer ${token()}`,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined}),d=await r.json();if(!r.ok)throw Error(d.error);return d};const id=()=>crypto.randomUUID();async function save(){const d=await call('PUT',{state,revision});state=d.state;revision=d.revision;render();$('hubStatus').textContent='Saved securely to your private School Hub.'}function render(){const now=new Date().toISOString().slice(0,10),next=[...state.exams].filter(x=>x.date>=now).sort((a,b)=>a.date.localeCompare(b.date))[0];$('nextExam').textContent=next?`${next.title} · ${next.date}`:'No upcoming exams';$('subjectList').innerHTML=state.subjects.map(x=>`<div class=hub-row><i class=hub-dot style="background:${x.color}"></i><strong>${esc(x.name)}</strong><button data-remove="subjects:${x.id}" class=hub-remove>Remove</button></div>`).join('')||'<p class=muted>Add subjects to colour-code your timetable.</p>';$('calendarList').innerHTML=[...state.terms.map(x=>({...x,kind:'Term'})),...state.holidays.map(x=>({...x,kind:'Holiday'}))].sort((a,b)=>a.start.localeCompare(b.start)).map(x=>`<div class=hub-row><span class=week-label>${x.kind}</span><strong>${esc(x.name)}</strong><small>${x.start} – ${x.end}</small><button data-remove="${x.kind==='Term'?'terms':'holidays'}:${x.id}" class=hub-remove>Remove</button></div>`).join('')||'<p class=muted>Add terms and holidays to align the year.</p>';$('blockList').innerHTML=state.blocks.sort((a,b)=>a.week.localeCompare(b.week)||a.day-b.day||a.start.localeCompare(b.start)).map(x=>`<div class=hub-row><span class=week-label>Week ${x.week}</span><strong>${esc(x.subject)}</strong><small>${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][x.day]} · ${x.start}–${x.end} · ${esc(x.label)}</small><button data-remove="blocks:${x.id}" class=hub-remove>Remove</button></div>`).join('')||'<p class=muted>Add class blocks for Week A and Week B.</p>';$('examList').innerHTML=state.exams.sort((a,b)=>a.date.localeCompare(b.date)).map(x=>`<div class=hub-row><strong>${esc(x.title)}</strong><small>${esc(x.subject)} · ${x.date}${x.room?' · '+esc(x.room):''}</small><button data-remove="exams:${x.id}" class=hub-remove>Remove</button></div>`).join('')||'<p class=muted>Add an exam to create a countdown.</p>'}function add(form,collection,fields){$(form).onsubmit=async e=>{e.preventDefault();state[collection].push({id:id(),...Object.fromEntries(fields.map(([source,key])=>[key,$(source).value]))});try{await save();e.target.reset()}catch(err){$('hubStatus').textContent=err.message}}}function bind(){add('subjectForm','subjects',[['subjectName','name'],['subjectColor','color']]);add('termForm','terms',[['termName','name'],['termStart','start'],['termEnd','end']]);add('holidayForm','holidays',[['holidayName','name'],['holidayStart','start'],['holidayEnd','end']]);add('blockForm','blocks',[['blockWeek','week'],['blockDay','day'],['blockSubject','subject'],['blockLabel','label'],['blockStart','start'],['blockEnd','end']]);add('examForm','exams',[['examTitle','title'],['examSubject','subject'],['examDate','date'],['examRoom','room']]);document.addEventListener('click',async e=>{const b=e.target.closest('[data-remove]');if(!b)return;const [collection,key]=b.dataset.remove.split(':');state[collection]=state[collection].filter(x=>x.id!==key);try{await save()}catch(err){$('hubStatus').textContent=err.message}})}async function load(){try{const d=await call('GET');state=d.state;revision=d.revision;render();$('hubStatus').textContent='School Hub is ready.'}catch(e){$('hubStatus').textContent=e.message}}bind();load();
